// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { Lightbox } from "@/registry/erbium/blocks/lightbox";
import type { Meta, StoryObj } from "@storybook/react";
import GalleryExample from "./variants/gallery";


const meta = {
  component: Lightbox,
  parameters: {
    docs: { description: { component: "## Installation

```sh
bunx shadcn@latest add @erbium/lightbox
```

With the default aliases, import the installed parts from `@/components/blocks/lightbox`. In a workspace using the Erbium UI package, import them from `@/registry/erbium/blocks/lightbox`.

## Composition

Use one `Lightbox` per gallery. Match each `LightboxTrigger` index to its `LightboxItem` index, starting at zero. Attach the trigger's `imageRef` to the thumbnail image for the open and close transitions. Give `LightboxMedia` the full image's dimensions so it can fit the image to the viewport before it loads.

The gallery example shows one `LightboxThumbnail` per slide in the footer. Nest the thumbnails inside `LightboxThumbnailStripTrack` and `LightboxThumbnailStrip`, and give each an accessible label and the index of its slide. For a single image, use one trigger and slide and omit the navigation controls and thumbnail strip. Use `createLightboxHandle` with the root's `handle` prop to open a slide from code.

## Slide indicator

Use `LightboxStepIndicator` inside `LightboxHeader` or `LightboxFooter` for clickable slide dots. It reads the slide count and active index from `Lightbox`, and stays synchronized with swipes, arrow buttons, and keyboard navigation. Every dot can select its slide directly, including jumping from first to last.

```tsx
<LightboxHeader className="justify-center">
  <LightboxStepIndicator labels={["Front view", "Side view", "Detail"]} />
</LightboxHeader>
```

`labels` supplies accessible names and hover/focus tooltips in slide order; otherwise the buttons are named “Slide 1”, “Slide 2”, and so on. The current slide is marked with `aria-current`, and slide changes are announced to screen readers. The indicator uses the design system's `StepIndicator` dots variant and replaces the numeric `LightboxCounter`.

## Accessibility

Give `LightboxContent` an accessible name and supply alt text for each image. The gallery supports keyboard navigation and returns focus to the trigger after closing. Click the background or press Escape to close it. Set the root's `dir` to `rtl` for a right-to-left gallery when direction is scoped below the document.

## External documentation

Erbium adapts Chánh Đại’s Lightbox composition and styles its controls with Erbium’s Button. Ramka supplies the underlying gallery, transitions, and gestures.

- [Chánh Đại’s Lightbox](https://chanhdai.com/components/lightbox)
- [Ramka documentation](https://ramka.dev/docs)" } },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Lightbox>;

export default { ...meta, title: "Blocks/Lightbox",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

export const Gallery: StoryObj = {
  parameters: {
    docs: {
      description: { story: "Open any image. Select an image in the bottom thumbnail strip, use the arrow keys, or swipe to change slides. Use the zoom buttons or pinch to inspect an image. Click the background or press Escape to close." },
      source: { code: "import {
  Lightbox,
  LightboxCaption,
  LightboxClose,
  LightboxContent,
  LightboxStepIndicator,
  LightboxFooter,
  LightboxHeader,
  LightboxItem,
  LightboxMedia,
  LightboxNext,
  LightboxPrevious,
  LightboxSlide,
  LightboxSlides,
  LightboxThumbnail,
  LightboxThumbnailStrip,
  LightboxThumbnailStripTrack,
  LightboxTrigger,
  LightboxZoom,
  LightboxZoomIn,
  LightboxZoomOut,
} from "@/registry/erbium/blocks/lightbox";

const photos = [
  {
    alt: "A workspace with long desks and hanging lights",
    caption: "Studio",
    src: "https://images.unsplash.com/photo-1497366754035-f200968a6e72",
  },
  {
    alt: "A plant-filled office with large windows",
    caption: "Office",
    src: "https://images.unsplash.com/photo-1497366811353-6870744d04b2",
  },
  {
    alt: "A workspace with a central table and chairs",
    caption: "Meeting room",
    src: "https://images.unsplash.com/photo-1497215728101-856f4ea42174",
  },
];

export default function GalleryExample() {
  return (
    <Lightbox>
      <div className="grid w-full max-w-md grid-cols-3 gap-3">
        {photos.map((photo, index) => (
          <LightboxTrigger
            aria-label={`Open ${photo.caption}`}
            className="overflow-hidden rounded-lg"
            index={index}
            key={photo.src}
          >
            {({ imageRef }) => (
              <img
                alt={photo.alt}
                className="aspect-[3/2] w-full object-cover"
                height={240}
                ref={imageRef}
                src={`${photo.src}?auto=format&fit=crop&w=360&h=240&q=80`}
                width={360}
              />
            )}
          </LightboxTrigger>
        ))}
      </div>

      <LightboxContent aria-label="Workspace photos">
        <LightboxSlides aria-label="Workspace photos" aria-roledescription="carousel">
          {photos.map((photo, index) => (
            <LightboxSlide key={photo.src}>
              <LightboxItem
                aria-label={`${index + 1} of ${photos.length}`}
                aria-roledescription="slide"
                caption={photo.caption}
                index={index}
              >
                <LightboxZoom>
                  <LightboxMedia height={1200} width={1800}>
                    <img
                      alt={photo.alt}
                      height={1200}
                      src={`${photo.src}?auto=format&fit=crop&w=1800&h=1200&q=85`}
                      width={1800}
                    />
                  </LightboxMedia>
                </LightboxZoom>
              </LightboxItem>
            </LightboxSlide>
          ))}
        </LightboxSlides>

        <LightboxHeader className="grid grid-cols-[1fr_auto_1fr]">
          <div />
          <LightboxStepIndicator labels={photos.map((photo) => photo.caption)} />
          <div className="flex items-center gap-2 justify-self-end">
            <LightboxZoomOut />
            <LightboxZoomIn />
            <LightboxClose />
          </div>
        </LightboxHeader>

        <LightboxPrevious />
        <LightboxNext />

        <LightboxFooter>
          <LightboxCaption />
          <LightboxThumbnailStrip>
            <LightboxThumbnailStripTrack aria-label="Workspace photo thumbnails">
              {photos.map((photo, index) => (
                <LightboxThumbnail aria-label={photo.caption} index={index} key={photo.src}>
                  <img
                    alt=""
                    height={112}
                    src={`${photo.src}?auto=format&fit=crop&w=112&h=112&q=75`}
                    width={112}
                  />
                </LightboxThumbnail>
              ))}
            </LightboxThumbnailStripTrack>
          </LightboxThumbnailStrip>
        </LightboxFooter>
      </LightboxContent>
    </Lightbox>
  );
}
" },
    },
  },
  render: GalleryExample,
};

